import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"自研、开源与采购","description":"","frontmatter":{"title":"自研、开源与采购","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/build-vs-buy.md","filePath":"frontend/decisions/build-vs-buy.md","lastUpdated":1785589115000}'),l={name:"frontend/decisions/build-vs-buy.md"};function i(o,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="自研、开源与采购" tabindex="-1">自研、开源与采购 <a class="header-anchor" href="#自研、开源与采购" aria-label="Permalink to &quot;自研、开源与采购&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>自研、采用开源方案和购买商业产品不是三种身份立场，而是三种责任分配方式。真正需要比较的是：谁承担研发、升级、安全响应、服务可用性和退出迁移，以及这些责任在整个使用周期内花费多少。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>团队常在“需求很特殊，所以必须自研”和“成熟产品一定更省钱”之间摆动。两句话都忽略了规模和生命周期：一个两周可完成的轻量能力可能不值得签三年合同，一个涉及虚拟滚动、可访问性和 Excel 交互的数据表格也不适合低估为几个组件。</p><p>本章以企业数据表格为案例，比较自研、开源和商业采购。相同方法也适用于监控、编辑器、身份平台和低代码能力。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-先检查准入条件" tabindex="-1">2.1 先检查准入条件 <a class="header-anchor" href="#_2-1-先检查准入条件" aria-label="Permalink to &quot;2.1 先检查准入条件&quot;">​</a></h3><p>候选方案必须先满足：</p><ul><li>许可证允许公司的分发和商业使用方式；</li><li>数据处理、遥测和远程服务符合隐私与数据驻留要求；</li><li>支持公司的浏览器、框架、无障碍和安全基线；</li><li>供应商合同、开源来源和制品能够通过供应链审查；</li><li>关键数据有可导出格式，不以供应商私有格式作为唯一副本。</li></ul><p>不满足其中一项，就应淘汰或先通过合同、配置和隔离措施消除冲突。</p><h3 id="_2-2-比较总拥有成本" tabindex="-1">2.2 比较总拥有成本 <a class="header-anchor" href="#_2-2-比较总拥有成本" aria-label="Permalink to &quot;2.2 比较总拥有成本&quot;">​</a></h3><p>总拥有成本不只包含授权费：</p><blockquote><p>TCO = 评估接入 + 定制开发 + 基础设施或订阅 + 升级适配 + 安全响应 + 用户支持 + 退出迁移</p></blockquote><p>用区间比伪精确数字更诚实，并分别估算第一年和稳定运行年。内部人力也有机会成本，不能按零计算。</p><h3 id="_2-3-识别战略差异化" tabindex="-1">2.3 识别战略差异化 <a class="header-anchor" href="#_2-3-识别战略差异化" aria-label="Permalink to &quot;2.3 识别战略差异化&quot;">​</a></h3><p>若能力直接构成产品差异、决定核心数据和客户体验，团队可能需要更高控制权。若能力是行业通用基础设施，购买成熟能力通常能把精力留给业务。但“核心”不等于“所有代码必须自己写”，关键是关键契约、数据和演进权是否在自己手中。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-自研" tabindex="-1">3.1 自研 <a class="header-anchor" href="#_3-1-自研" aria-label="Permalink to &quot;3.1 自研&quot;">​</a></h3><p>自研提供最大定制空间和路线控制，但团队承担需求澄清、浏览器兼容、性能、无障碍、安全修复、文档和长期支持。适合需求窄而稳定、确有差异化，或外部方案无法满足硬约束的场景。</p><h3 id="_3-2-开源" tabindex="-1">3.2 开源 <a class="header-anchor" href="#_3-2-开源" aria-label="Permalink to &quot;3.2 开源&quot;">​</a></h3><p>开源方案允许审查代码并避免单一商业合同，但不等于免费或有人负责。需要检查维护活跃度、核心维护者集中度、版本策略、许可证、漏洞响应和自行 fork 后的维护能力。</p><h3 id="_3-3-商业采购" tabindex="-1">3.3 商业采购 <a class="header-anchor" href="#_3-3-商业采购" aria-label="Permalink to &quot;3.3 商业采购&quot;">​</a></h3><p>商业产品以授权费换取功能、支持、SLA 或合规承诺。采购价值取决于合同是否覆盖真实风险；只有销售承诺而没有版本、响应时间、数据导出和终止条款，不能计入可靠收益。</p><h3 id="_3-4-组合方案" tabindex="-1">3.4 组合方案 <a class="header-anchor" href="#_3-4-组合方案" aria-label="Permalink to &quot;3.4 组合方案&quot;">​</a></h3><p>常见最优解是组合：使用开源核心并购买企业支持；购买通用引擎但自研领域层；先采购验证需求，再把稳定且差异化的部分内建。组合方案仍需明确问题发生时由谁负责。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例约束：12 周交付供应链运营台；需要 10 万行服务端数据、列冻结、分组、键盘操作、导出和审计；5 名开发者中没有表格引擎经验；计划使用至少三年。</p><table tabindex="0"><thead><tr><th>维度</th><th>自研</th><th>开源社区版</th><th>商业组件</th></tr></thead><tbody><tr><td>首期交付</td><td>高风险，预计 5 至 8 人月</td><td>中等，缺少部分高级功能</td><td>低风险，原型覆盖主要需求</td></tr><tr><td>三年现金成本</td><td>低授权费，高人力</td><td>低授权费，中等维护</td><td>授权费明确，中等集成维护</td></tr><tr><td>可访问性</td><td>需自行设计和验证</td><td>基础能力可用</td><td>有审计报告和修复承诺</td></tr><tr><td>定制能力</td><td>最高</td><td>受公开扩展点限制</td><td>受产品和合同限制</td></tr><tr><td>升级责任</td><td>完全内部承担</td><td>内部适配上游版本</td><td>供应商发布，内部仍需回归</td></tr><tr><td>退出成本</td><td>领域契约可控</td><td>API 迁移成本中等</td><td>私有配置和授权终止风险较高</td></tr></tbody></table><p>这里没有用“功能数量”直接评分。只有验收范围中的功能才产生价值，未使用的高级功能不应提高得分。</p><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>本案例选择商业组件，并自研一层领域适配器。决定依据是 12 周期限、复杂交互和团队经验，而不是商业方案天然更优。采购合同必须包含版本支持、漏洞响应、无障碍修复、离线构建和配置导出条款。</p><p>领域层只向页面公开列定义、筛选、选择和导出契约，不让业务组件直接依赖供应商的全部 API。这样既获得成熟引擎，也保留替换边界。</p><p>以下场景会得到不同结论：只有几百行数据和基础排序时，原生表格加少量自研可能最合适；数据驻留或许可证无法满足时，商业候选应直接淘汰；表格交互本身是产品核心且团队具备引擎能力时，自研价值会上升。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>选择商业组件后，首期风险下降，但团队接受年度授权、供应商版本节奏和部分 API 锁定。仍需安排集成测试、升级窗口和内部一线支持，不能把产品责任完全转给供应商。</p><p>负责人应维护：依赖版本、许可证席位、合同到期日、关键问题响应、替代方案和数据导出演练。采购完成不是决策生命周期的终点。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要为一次性、小范围需求启动漫长采购流程。</li><li>不要因“代码可见”就假设开源方案没有供应链和维护风险。</li><li>不要把内部工程师成本隐去后宣称自研最便宜。</li><li>不要购买无法导出数据、无法离线构建且没有终止协助的核心平台。</li><li>不要因沉没成本继续保留已经不满足约束的方案。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>供应链运营台的数据表格能力从哪里获得</td></tr><tr><td>硬约束</td><td>12 周交付；无障碍 AA；无外部遥测；10 万行服务端数据；三年支持</td></tr><tr><td>候选</td><td>自研、开源社区版、商业组件、开源加企业支持</td></tr><tr><td>决定</td><td>采购商业组件，自研领域适配器</td></tr><tr><td>证据</td><td>两周原型通过 18 项验收中的 17 项；自研估算为 5 至 8 人月</td></tr><tr><td>接受代价</td><td>年度授权；升级依赖供应商；适配层维护</td></tr><tr><td>退出路径</td><td>列、筛选和选择状态使用内部 Schema；每半年验证 CSV/JSON 导出</td></tr><tr><td>负责人</td><td>运营平台技术负责人和采购负责人</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>合同续签前六个月例行复查；出现以下任一情况时提前启动：年度成本增长超过 25%、关键缺陷超过 SLA 两次、框架新版本六个月内仍不受支持、适配层无法隔离私有 API、数据导出演练失败，或表格能力开始成为产品差异化核心。</p>',43)])])}const b=a(l,[["render",i]]);export{u as __pageData,b as default};
